def ref_url(row):
    key, author, title, year, journal, volume, number, pages, doi, arxiv = row
    if key == 'ke2026': return 'https://www3.stat.sinica.edu.tw/statistica/fp/SS-2026-0222.html'
    if key == 'liuleezhang2024': return 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11046526/'
    if key == 'luzhulian2020': return 'https://www.jmlr.org/papers/v21/20-383.html'
    if key == 'donoho1994': return 'https://web.stanford.edu/dept/statistics/cgi-bin/donoho/wp-content/uploads/2018/08/SEOR.pdf'
    if key == 'dufour1997': return 'https://jeanmariedufour.github.io/Dufour_1994_ImpossibilityTheorems_W.pdf'
    return 'https://arxiv.org/abs/' + arxiv if arxiv else 'https://doi.org/' + doi

def build():
    with (ROOT/'closest_papers.csv').open('w', newline='') as f:
        writer = csv.writer(f); writer.writerow(FIELDS); writer.writerows(ROWS)
    (ROOT/'closest_papers.json').write_text(json.dumps([dict(zip(FIELDS,r)) for r in ROWS],indent=2))
    (ROOT/'supplementary_paper_records.json').write_text(json.dumps([dict(zip(FIELDS,r)) for r in SUPPLEMENTARY_ROWS],indent=2))
    bib=[]; refs=[]
    for i,r in enumerate(REFS,1):
        key,author,title,year,journal,volume,number,pages,doi,arxiv=r
        fields={'author':author,'title':'{'+title+'}','year':year,'journal':journal,'volume':volume,'number':number,'pages':pages,'doi':doi,'eprint':arxiv,'archivePrefix':'arXiv' if arxiv else '', 'url':ref_url(r)}
        if key=='armstrong2026': fields['note']='In press; accepted-paper record verified. Full text examined: arXiv v3, December 2024.'
        if key=='ke2026': fields['note']='Newly accepted preprint SS-2026-0222; updated September 8, 2026. No volume or pages assigned in inspected record.'
        if key=='carpentieretal2015': fields['note']='Cited as the verified 2015 arXiv version; a 2019 published version is recorded in the Freie Universitaet Berlin repository.'
        bib.append('@'+('article' if journal else 'misc')+'{'+key+',\n'+',\n'.join('  '+k+' = {'+v+'}' for k,v in fields.items() if v)+'\n}\n')
        venue=journal or 'arXiv preprint'
        detail=(' '+volume+('('+number+')' if number else '')+(':'+pages.replace('--','–') if pages else '')) if volume else ''
        extra = ' Accepted preprint, updated September 8, 2026.' if key=='ke2026' else (' In press; December 2024 preprint examined.' if key=='armstrong2026' else '')
        doi_link=' [DOI](https://doi.org/'+doi+').' if doi else ''
        refs.append(f'{i}. **R{i:02d}**. {author.replace(" and ", "; ")} ({year}). [{title}]({ref_url(r)}). *{venue}*{detail}.{extra}{doi_link}')
    (ROOT/'references.bib').write_text('\n'.join(bib))
    (ROOT/'bibliography.md').write_text('# Verified key references\n\nCutoff: September 9, 2026. Preprint year, online publication year, and issue year are distinguished. Numbering matches the assessment.\n\n'+'\n\n'.join(refs)+'\n')
    lines=['## B. Ranked closest-paper matrix','', 'Threat ranks concern the proposed claims, not paper quality. Rates use each paper’s observation model and normalization. A theorem locator refers to the inspected full-text version; it may differ from the journal version. Detailed assumptions should be rechecked before reusing a theorem.','', '| Rank / paper | Statistical problem and method | Assumptions and asymptotic regime | Main theorem / rate or guarantee | Limitation; mathematical difference; threat |','|---|---|---|---|---|']
    for row in ROWS:
        d=dict(zip(FIELDS,row)); ref=REFS[int(d['reference'][1:])-1]
        d={k:(v.replace('|',r'\|') if isinstance(v,str) else v) for k,v in d.items()}
        label=ref[1].split(',')[0]+' et al.' if ' and ' in ref[1] else ref[1].split(',')[0]
        lines.append(f"| {d['rank']}. [{d['reference']}: {label} ({ref[3]})]({ref_url(ref)}) | {d['problem']} {d['method']} | {d['assumptions']} {d['asymptotic_regime']} | {d['main_theorem']} {d['rate_or_guarantee']} | {d['limitation_and_mathematical_difference']} **{d['novelty_threat']}.** |")
    (ROOT/'closest_papers.md').write_text('\n'.join(lines)+'\n')
    core=(ROOT/'assessment_core.md').read_text().replace('<!-- MATRIX_AND_BIBLIOGRAPHY_APPENDED_BY_BUILD -->','')
    # Keep the full assessment self-contained and place the matrix before the analysis.
    matrix='\n'.join(lines)+'\n\n'
    core=core.replace('## 2. Elementary checks', matrix+'## 2. Elementary checks')
    bibliography=(ROOT/'bibliography.md').read_text().replace('# Verified key references','## G. Verified key references',1)
    (ROOT/'assessment.md').write_text(core+'\n'+bibliography)

if __name__=='__main__': build()
